  "message": "#12 [stage-0 5/5] RUN --mount=type=secret,id=render-env,target=/run/secrets/render-env --mount=type=secret,id=bex-file-0,target=/etc/secrets/qa-note.txt,required=true [\"/bin/bash\",\"-c\",\". /opt/bex/load-env\\n/bin/cat \u003e qa_probe.exs \u003c\u003c'QA240_ELIXIR'\\ndefmodule Probe do\\n def snap do\\n  b=File.read!(\"/etc/secrets/qa-note.txt\")\\n  marker=System.fetch_env!(\"QA_MARKER\")\\n  path=System.fetch_env!(\"PATH\")\\n  # These owned marker/PATH fixtures contain no JSON metacharacters.\\n  hex=Base.encode16(b,case: :lower)\\n  ~s({\"marker\":\"#{marker}\",\"path\":\"#{path}\",\"fileHex\":\"#{hex}\"})\\n end\\n def serve(listener,built) do\\n  {:ok,socket}=:gen_tcp.accept(listener)\\n  case :gen_tcp.recv(socket,0,5000) do\\n   {:ok,_request}-\u003e\\n    payload = ~s({\"built\":#{built},\"runtime\":#{snap()}})\\n    :gen_tcp.send(socket,\"HTTP/1.1 200 OK\\r\\nContent-Type: application/json\\r\\nContent-Length: #{byte_size(payload)}\\r\\nConnection: close\\r\\n\\r\\n\"\u003c\u003epayload)\\n   _-\u003e:ok\\n  end\\n  :gen_tcp.close(socket)\\n  serve(listener,built)\\n end\\nend\\nif System.argv()==[\"--snapshot\"] do\\n IO.puts(Probe.snap())\\nelse\\n built=File.read!(\"qa-built.json\") |\u003e String.trim()\\n port=System.get_env(\"PORT\",\"3000\") |\u003e String.to_integer()\\n {:ok,listener}=:gen_tcp.listen(port,[:binary,active: false,reuseaddr: true,packet: :raw])\\n Probe.serve(listener,built)\\nend\\nQA240_ELIXIR\\n/usr/local/bin/elixir qa_probe.exs --snapshot \u003e qa-built.json\"]",
